redmapViewBase::~redmapViewBase()
{

}

void redmapViewBase::setupScreen()
{

}

void redmapViewBase::handleKeyEvent(uint8_t key)
{
    if(23 == key)
    {
        //changescreen
        //When hardware button 23 clicked change screen to screen
        //Go to screen with no screen transition
        application().gotoscreenScreenNoTransition();
    
    }
}

void redmapViewBase::handleTickEvent()
{
    frameCountUPdate2Interval++;
    if(frameCountUPdate2Interval == TICK_UPDATE2_INTERVAL)
    {
        //UPdate2
        //When every N tick call virtual function
        //Call update2
        update2();
        frameCountUPdate2Interval = 0;
    }
}
